#!/usr/bin/env bun

/**
 * JSON Validator Script
 *
 * Reads JSON from stdin and validates it can be parsed.
 * Exits with code 0 for valid JSON, 1 for invalid JSON.
 *
 * Usage:
 *   echo '{"key": "value"}' | bun run scripts/validate-json.ts
 *   cat file.json | bun run scripts/validate-json.ts
 */

async function validateJson(): Promise<void> {
  try {
    const stdin = await Bun.stdin.text();

    if (!stdin || stdin.trim().length === 0) {
      console.error("Error: No input provided");
      process.exit(1);
    }

    JSON.parse(stdin);
    console.log("✓ Valid JSON");
    process.exit(0);
  } catch (error) {
    if (error instanceof SyntaxError) {
      console.error(`✗ Invalid JSON: ${error.message}`);
    } else {
      console.error(`✗ Error: ${error instanceof Error ? error.message : String(error)}`);
    }
    process.exit(1);
  }
}

validateJson();

