import { describe, expect, test } from "bun:test";
import { greet, add, greetWithTime } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  describe("greetWithTime", () => {
    test("returns morning greeting for hours 5-11", () => {
      expect(greetWithTime("Alice", 5)).toBe("Good morning, Alice!");
      expect(greetWithTime("Bob", 11)).toBe("Good morning, Bob!");
    });

    test("returns afternoon greeting for hours 12-16", () => {
      expect(greetWithTime("Alice", 12)).toBe("Good afternoon, Alice!");
      expect(greetWithTime("Bob", 16)).toBe("Good afternoon, Bob!");
    });

    test("returns evening greeting for hours 17-23 and 0-4", () => {
      expect(greetWithTime("Alice", 17)).toBe("Good evening, Alice!");
      expect(greetWithTime("Bob", 23)).toBe("Good evening, Bob!");
      expect(greetWithTime("Charlie", 0)).toBe("Good evening, Charlie!");
      expect(greetWithTime("Dave", 4)).toBe("Good evening, Dave!");
    });
  });
});

