import { describe, expect, test } from "bun:test";
import { greet, add, validateJSON, type JSONSchema } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("validateJSON", () => {
  describe("basic validation", () => {
    test("validates object with required string field", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          name: { type: "string", required: true },
        },
      };
      const data = { name: "Alice" };
      const result = validateJSON(data, schema);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("rejects object missing required field", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          name: { type: "string", required: true },
        },
      };
      const data = {};
      const result = validateJSON(data, schema);
      expect(result.valid).toBe(false);
      expect(result.errors).toContain("Missing required field: name");
    });

    test("rejects object with incorrect type", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          age: { type: "number", required: true },
        },
      };
      const data = { age: "not a number" };
      const result = validateJSON(data, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
    });
  });

  describe("type checking", () => {
    test("validates string type", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
        },
      };
      expect(validateJSON({ name: "Alice" }, schema).valid).toBe(true);
      expect(validateJSON({ name: 123 }, schema).valid).toBe(false);
    });

    test("validates number type", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          age: { type: "number" },
        },
      };
      expect(validateJSON({ age: 25 }, schema).valid).toBe(true);
      expect(validateJSON({ age: "25" }, schema).valid).toBe(false);
    });

    test("validates boolean type", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          active: { type: "boolean" },
        },
      };
      expect(validateJSON({ active: true }, schema).valid).toBe(true);
      expect(validateJSON({ active: "true" }, schema).valid).toBe(false);
    });

    test("validates object type", () => {
      const schema: JSONSchema = {
        type: "object",
        properties: {
          data: { type: "object" },
        },
      };
      expect(validateJSON({ data: {} }, schema).valid).toBe(true);
      expect(validateJSON({ data: [] }, schema).valid).toBe(false);
    });
  });
});

