/**
 * Validates a JSON data structure against a schema definition.
 *
 * @param data - The data to validate
 * @param schema - The schema to validate against
 * @returns Validation result with valid flag and error messages
 *
 * @example
 * ```typescript
 * const schema: JSONSchema = {
 *   type: "object",
 *   properties: {
 *     name: { type: "string", required: true },
 *     age: { type: "number", required: true }
 *   }
 * };
 *
 * const result = validateJSON({ name: "Alice", age: 30 }, schema);
 * if (result.valid) {
 *   console.log("Valid data");
 * } else {
 *   console.error("Validation errors:", result.errors);
 * }
 * ```
 */
export function validateJSON(data: unknown, schema: JSONSchema): ValidationResult {
  const errors: string[] = [];

  function validateValue(value: unknown, propSchema: PropertySchema, path: string): void {
    const actualType = getJSONType(value);

    if (actualType !== propSchema.type) {
      errors.push(`Type mismatch at ${path}: expected ${propSchema.type}, got ${actualType}`);
      return;
    }

    if (propSchema.type === "object" && propSchema.properties) {
      if (value === null || typeof value !== "object" || Array.isArray(value)) {
        return;
      }

      const obj = value as Record<string, unknown>;

      for (const [key, keySchema] of Object.entries(propSchema.properties)) {
        if (keySchema.required && !(key in obj)) {
          errors.push(`Missing required field: ${key}`);
          continue;
        }

        if (key in obj) {
          validateValue(obj[key], keySchema, `${path}.${key}`);
        }
      }
    }

    if (propSchema.type === "array" && propSchema.items) {
      if (!Array.isArray(value)) {
        return;
      }

      value.forEach((item, index) => {
        validateValue(item, propSchema.items!, `${path}[${index}]`);
      });
    }
  }

  if (schema.type === "object" && schema.properties) {
    if (data === null || typeof data !== "object" || Array.isArray(data)) {
      errors.push(`Type mismatch at root: expected object, got ${getJSONType(data)}`);
      return { valid: false, errors };
    }

    const obj = data as Record<string, unknown>;

    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (propSchema.required && !(key in obj)) {
        errors.push(`Missing required field: ${key}`);
        continue;
      }

      if (key in obj) {
        validateValue(obj[key], propSchema, key);
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function getJSONType(value: unknown): JSONType {
  if (value === null) {
    return "null";
  }

  if (Array.isArray(value)) {
    return "array";
  }

  const jsType = typeof value;

  if (jsType === "string" || jsType === "number" || jsType === "boolean") {
    return jsType;
  }

  if (jsType === "object") {
    return "object";
  }

  return "null";
}

