   129→ *   type: "object",
   130→ *   properties: {
   131→ *     user: {
   132→ *       type: "object",
   133→ *       required: true,
   134→ *       properties: {
   135→ *         name: { type: "string", required: true },
   136→ *         email: { type: "string", required: true }
   137→ *       }
   138→ *     }
   139→ *   }
   140→ * };
   141→ *
   142→ * const data = {
   143→ *   user: { name: "Bob", email: "bob@example.com" }
   144→ * };
   145→ * const result = validateJSON(data, schema);
   146→ * ```
