   198→export function validateJSON(data: unknown, schema: JSONSchema): ValidationResult {
   199→  const errors: string[] = [];
   200→
   201→  function validateValue(value: unknown, propSchema: PropertySchema, path: string): void {
   202→    const actualType = getJSONType(value);
   203→
   204→    if (actualType !== propSchema.type) {
   205→      errors.push(`Type mismatch at ${path}: expected ${propSchema.type}, got ${actualType}`);
   206→      return;
   207→    }
   208→
   209→    if (propSchema.type === "object" && propSchema.properties) {
   210→      if (value === null || typeof value !== "object" || Array.isArray(value)) {
   211→        return;
   212→      }
   213→
   214→      const obj = value as Record<string, unknown>;
   215→
   216→      for (const [key, keySchema] of Object.entries(propSchema.properties)) {
   217→        if (keySchema.required && !(key in obj)) {
   218→          errors.push(`Missing required field: ${key}`);
   219→          continue;
   220→        }
   221→
   222→        if (key in obj) {
   223→          validateValue(obj[key], keySchema, `${path}.${key}`);
   224→        }
   225→      }
   226→    }
   227→
   228→    if (propSchema.type === "array" && propSchema.items) {
   229→      if (!Array.isArray(value)) {
   230→        return;
   231→      }
   232→
   233→      value.forEach((item, index) => {
   234→        validateValue(item, propSchema.items!, `${path}[${index}]`);
   235→      });
   236→    }
   237→  }
   238→
   239→  if (schema.type === "object" && schema.properties) {
   240→    if (data === null || typeof data !== "object" || Array.isArray(data)) {
   241→      errors.push(`Type mismatch at root: expected object, got ${getJSONType(data)}`);
   242→      return { valid: false, errors };
   243→    }
   244→
   245→    const obj = data as Record<string, unknown>;
   246→
   247→    for (const [key, propSchema] of Object.entries(schema.properties)) {
   248→      if (propSchema.required && !(key in obj)) {
   249→        errors.push(`Missing required field: ${key}`);
   250→        continue;
   251→      }
   252→
   253→      if (key in obj) {
   254→        validateValue(obj[key], propSchema, key);
   255→      }
   256→    }
   257→  }
   258→
   259→  return {
   260→    valid: errors.length === 0,
   261→    errors,
   262→  };
   263→}
   264→
   265→function getJSONType(value: unknown): JSONType {
   266→  if (value === null) {
   267→    return "null";
   268→  }
   269→
   270→  if (Array.isArray(value)) {
   271→    return "array";
   272→  }
   273→
   274→  const jsType = typeof value;
   275→
   276→  if (jsType === "string" || jsType === "number" || jsType === "boolean") {
   277→    return jsType;
   278→  }
   279→
   280→  if (jsType === "object") {
   281→    return "object";
   282→  }
   283→
   284→  return "null";
   285→}
