/**
 * Supported JSON primitive types for validation.
 *
 * - `string`: Text values
 * - `number`: Numeric values (integers or floats)
 * - `boolean`: true or false
 * - `object`: Plain objects (not arrays or null)
 * - `array`: Array values
 * - `null`: Explicit null value
 */
export type JSONType = "string" | "number" | "boolean" | "object" | "array" | "null";

/**
 * Schema definition for a single property.
 *
 * Defines the expected type and constraints for a property in a JSON object.
 *
 * @property type - The expected JSON type
 * @property required - Whether the property must be present (default: false)
 * @property properties - For object types, defines nested property schemas
 * @property items - For array types, defines the schema for array items
 *
 * @example
 * ```typescript
 * const userSchema: PropertySchema = {
 *   type: "object",
 *   required: true,
 *   properties: {
 *     name: { type: "string", required: true },
 *     age: { type: "number" }
 *   }
 * };
 * ```
 */
export interface PropertySchema {
  type: JSONType;
  required?: boolean;
  properties?: Record<string, PropertySchema>;
  items?: PropertySchema;
}

/**
 * JSON schema definition for validation.
 *
 * Top-level schema that describes the structure of a JSON document.
 *
 * @property type - The root type (typically "object")
 * @property properties - Property schemas for object types
 * @property items - Item schema for array types
 *
 * @example
 * ```typescript
 * const schema: JSONSchema = {
 *   type: "object",
 *   properties: {
 *     id: { type: "number", required: true },
 *     tags: { type: "array", items: { type: "string" } }
 *   }
 * };
 * ```
 */
export interface JSONSchema {
  type: JSONType;
  properties?: Record<string, PropertySchema>;
  items?: PropertySchema;
}

/**
 * Result of JSON validation.
 *
 * @property valid - True if validation passed, false otherwise
 * @property errors - Array of error messages describing validation failures
 */
export interface ValidationResult {
  valid: boolean;
  errors: string[];
}

